mapper.select:
SELECT dept_name AS deptName, NVL(SUM(refund_count), 0) AS refundCount, MAX(refund_rate) AS refundRate, NVL(SUM(no_show_count), 0) AS noShowCount, MAX(no_show_rate) AS noShowRate FROM TR_NOSHOW_DTL WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_name LIKE '%' || #{deptName} || '%'
GROUP BY dept_name ORDER BY refundCount DESC

SELECT item_name AS itemName, NVL(SUM(item_value), 0) AS itemValue FROM TR_NOSHOW_ORG WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND origin_type = #{originType}
GROUP BY item_name ORDER BY itemValue DESC

SELECT item_name AS itemName, NVL(SUM(item_value), 0) AS itemValue FROM TR_NOSHOW_CHN WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND channel_type = #{channelType}
GROUP BY item_name ORDER BY itemValue DESC
